-- Guia "Sintra em 4 dias: ingresso da Pena sem tolerância de horário, Regaleira e Monserrate" (rascunho). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/sintra-em-4-dias.json.
-- Entra como rascunho: publique pelo painel (/admin-blog.html) depois de conferir a pré-visualização.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('661bd6b7-5e36-4e5d-a049-7ff33254cc8a', 'sintra-em-4-dias', 'draft', 'portugal', 'Sintra em 4 dias: ingresso da Pena sem tolerância de horário, Regaleira e Monserrate', 'ingresso da Pena sem tolerância de horário', 'Roteiro de Sintra em 4 dias com Palácio da Pena, Castelo dos Mouros, Palácio Nacional, Regaleira, Monserrate, Capuchos, Cabo da Roca e Queluz, valores em euros e em reais e o guia em PDF para baixar de graça.', 'O ingresso do Palácio da Pena tem dia e hora, e a hora é a da porta do palácio, sem tolerância de atraso. Chegar antes também barra a entrada. O roteiro, os valores e o guia completo vão no celular.', 'Sintra', NULL, '/assets/blog/sintra-4-dias.jpg', '/assets/blog/sintra-4-dias-m.jpg', 'Palácio da Pena, em Sintra, foto de capa do roteiro de 4 dias', 0, '[{"t":"pdf","href":"/guias/sintra-em-4-dias.pdf","note":"PDF de 16 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Palácio Nacional, Regaleira, Castelo dos Mouros e Pena, Monserrate e Capuchos, Cabo da Roca e Queluz, com horários sugeridos, valores em euro e em reais e checklist."},{"t":"tip","items":["**Antes de tudo, o ingresso da Pena:** ele tem dia e hora, e não existe tolerância de atraso. Chegar antes também barra a entrada, e faltar não dá troca nem reembolso. A hora é a da porta do palácio, não a do parque: preveja cerca de 30 minutos da entrada do parque até lá.","**Não confunda com a Regaleira:** ela também tem bilhete com data e hora, mas aceita até 1 hora de atraso. Compre os dois online e antes. No Parques de Sintra, a compra online antecipada permite reagendar dia e hora por um ano.","Os horários do roteiro são sugestões da Rota Certa, não dados oficiais. Os avisos mudam: veja os avisos do Parques de Sintra antes de ir.","Veja as seções Documentos e antes de ir e Valores oficiais e fontes."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Vila de Sintra","label":"Dia 1"},{"t":"p","text":"Palácio Nacional, travesseiro e Regaleira, na vila e arredores, em ritmo leve."},{"t":"img","src":"/assets/blog/sintra-palacio-nacional.jpg","alt":"Palácio Nacional de Sintra com as duas chaminés cônicas","caption":"Palácio Nacional de Sintra e as suas chaminés cônicas.","credit":"Foto: Jeffrey Eisen / Pexels","w":1000,"h":667},{"t":"ul","items":["**9h00, Estação de Sintra:** Chegada de trem da CP, Linha de Sintra, saindo de Oriente, Rossio ou Entrecampos. Tempo e tarifa do trem: confirme no site da CP. Dali você segue para o centro histórico.","**9h30, Palácio Nacional de Sintra:** Cerca de 1h30. Abre às 9h30, última entrada às 17h30. Visita Essencial: € 13 (cerca de R$ 85); jardins de entrada livre. A bilheteria fecha das 12h00 às 13h00, com máquina automática. Destaques: Sala dos Cisnes, Sala das Pegas, Cozinha com as chaminés cônicas e Gruta das Águas.","**11h30, Travesseiro na Piriquita:** Antiga Casa de Queijadas, na Rua das Padarias 1, fundada em 1862. O site da Câmara de Sintra diz que os travesseiros mais famosos são feitos lá. Horário e preço: confirme no local.","**12h30, Almoço:** Veja a seção Sabores.","**14h00, Quinta da Regaleira:** Cerca de 2h30. € 20 (cerca de R$ 130). Bilhete só online, pessoal, com data e hora. Aceita até 1 hora de atraso sobre a hora do bilhete; reagende até 48 horas antes; em geral, sem reembolso nem troca. Abre das 10h00 às 18h30 (outubro a dezembro), última entrada às 17h30.","**17h30, Fim do dia:** Saia por volta das 17h30, antes de a Regaleira fechar, às 18h30."]},{"t":"tip","items":["Sem mala, carrinho nem mochila grande. O poço só se percorre descendo. O ônibus 435 para na Regaleira. A Regaleira fecha em 1/1, 24/12, 25/12 e 31/12."],"title":"Regaleira: o que levar e o que evitar"},{"t":"tip","items":["Em 15/12/2026, a Sala dos Cisnes do Palácio Nacional terá visita condicionada. No centro histórico, carro particular só de moradores."],"title":"Avisos para este dia"},{"t":"tip","items":["Principal: Palácio Nacional e Quinta da Regaleira","Grátis: Jardins do Palácio Nacional","Opcional: Travesseiro na Piriquita","**Nas atrações:** cerca de 4 horas","**A pé:** o mapa do dia traça o trajeto a pé entre a estação, o Palácio Nacional, a Piriquita e a Regaleira. O site oficial cita 10 a 15 minutos da estação ao Palácio Nacional, sem dizer se a pé ou de ônibus","**Esforço:** leve, no centro histórico","Estimativas da Rota Certa, não dados oficiais. Não contam filas nem refeições.","**Dica da Rota Certa:** compre o ingresso da Regaleira online e antes. Ele aceita até 1 hora de atraso, ao contrário do da Pena."],"title":"Para planejar o Dia 1"},{"t":"p","text":"[Abrir a rota do Dia 1 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Esta%C3%A7%C3%A3o%20de%20Sintra&waypoints=Pal%C3%A1cio%20Nacional%20de%20Sintra%7CPiriquita%2C%20Rua%20das%20Padarias%201%2C%20Sintra&destination=Quinta%20da%20Regaleira%2C%20Sintra&travelmode=walking)"},{"t":"passeio","busca":"Sintra centro histórico passeio","title":"Passeios em Sintra"},{"t":"h","text":"Pena e Castelo dos Mouros","label":"Dia 2"},{"t":"p","text":"Castelo dos Mouros e Palácio da Pena: a hora do ingresso manda no dia."},{"t":"img","src":"/assets/blog/sintra-castelo-mouros.jpg","alt":"Castelo dos Mouros, no alto da serra de Sintra","caption":"Castelo dos Mouros, no alto da serra de Sintra.","credit":"Foto: Luciano Dassiê / Pexels","w":1000,"h":645},{"t":"ul","items":["**9h00, Estação de Sintra:** Ônibus 434 rumo ao Castelo dos Mouros.","**9h30, Castelo dos Mouros:** Cerca de 1h30, subida exigente. Das 9h30 às 18h00, última entrada às 17h30. € 12 (cerca de R$ 78). A bilheteria fecha das 12h00 às 13h00.","**11h00, Rumo à Pena:** Volte ao 434 e suba (tempo de ônibus sem fonte: deixe folga). Chegue à entrada do parque por volta das 12h00: 30 minutos de folga além dos 30 que o site manda prever.","**12h30, Palácio da Pena:** Hora sugerida; a hora real você escolhe na compra. Visita essencial: € 20 (cerca de R$ 130), com a Ala Nova e o parque. Visita total: € 45 (cerca de R$ 292), com os apartamentos privados. Só o parque: € 12 (cerca de R$ 78). Transfer ida e volta: + € 4,50 (cerca de R$ 30). Palácio das 9h30 às 18h30. Armários para mochila na entrada principal.","**14h30, Almoço e parque:** Cafetarias: veja a seção Sabores. Parque das 9h00 às 19h00 (última entrada às 18h00); Chalet da Condessa d''Edla das 9h00 às 17h30 (última entrada às 17h00), incluído nos bilhetes. Confirme no site se o portão do chalet fecha ao meio-dia. Volta no 434: confirme no site do operador a última saída da Pena."]},{"t":"tip","items":["O ingresso do palácio vale na data e na hora que você escolheu. \"Se chegar ao Palácio antes da hora que reservou, não poderá entrar.\" Depois da hora, também não entra e o bilhete não é reembolsado. \"Não existe tolerância de atraso.\" Faltar não dá troca nem reembolso.","A hora do bilhete é a de entrada no palácio, não no parque: preveja cerca de 30 minutos da entrada do parque até lá. Um pequeno transfer sai da entrada principal e passa a cada 15 minutos; o bilhete dele deve ser comprado antes."],"title":"Pena: dia e hora, sem tolerância"},{"t":"tip","items":["Carro particular não é permitido no acesso à Pena e ao Castelo dos Mouros. Use o ônibus 434, que sai da estação de Sintra."],"title":"Como chegar à Pena e ao Castelo"},{"t":"tip","items":["Principal: Palácio da Pena, com ingresso de dia e hora","Grátis: sem atração gratuita neste dia","Opcional: Visita total da Pena, transfer e Hop On Hop Off da Pena","**Nas atrações:** Castelo dos Mouros cerca de 1h30; a Pena não tem duração oficial, reserve folga","**A pé:** subida exigente no Castelo dos Mouros; o acesso é de ônibus 434, porque carro particular não é permitido","**Esforço:** exigente, pela subida do castelo","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** leve água e um lanche, porque várias cafetarias da serra estão fechadas."],"title":"Para planejar o Dia 2"},{"t":"p","text":"[Abrir a rota do Dia 2 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Esta%C3%A7%C3%A3o%20de%20Sintra&waypoints=Castelo%20dos%20Mouros%2C%20Sintra&destination=Pal%C3%A1cio%20da%20Pena%2C%20Sintra&travelmode=transit)"},{"t":"passeio","busca":"Sintra Palácio da Pena passeio","title":"Passeios para a Pena e o Castelo dos Mouros"},{"t":"h","text":"Monserrate e Capuchos","label":"Dia 3"},{"t":"p","text":"Monserrate de manhã e Capuchos à tarde, se estiver aberto, do outro lado da serra e em ritmo médio."},{"t":"img","src":"/assets/blog/sintra-monserrate.jpg","alt":"Palácio de Monserrate e jardins, em Sintra","caption":"Palácio de Monserrate e os seus jardins.","credit":"Foto: Andreas Neubauer / Pexels","w":1000,"h":667},{"t":"ul","items":["**9h30, Estação de Sintra:** Ônibus 1253 ou 435 até Monserrate. Horários do 1253: confirme no site da Carris Metropolitana.","**10h00, Monserrate:** Cerca de 2h30. Parque das 9h00 às 19h00; palácio das 9h30 às 18h00 (último bilhete às 17h00). € 12 (cerca de R$ 78). A bilheteria fecha das 12h00 às 13h00. O roteiro oficial cita Cascata de Beckford, Vale dos Fetos, Jardim do México e Biblioteca. O palácio está com andaimes.","**12h30, Almoço:** A casa de chá reabre só em 02/12/2026. Veja a seção Sabores.","**14h00, Rumo aos Capuchos:** De carro, o roteiro oficial leva cerca de 30 minutos de Monserrate; de ônibus, o site dos Capuchos cita o 1253 a partir de Sintra. Tempo total de ônibus: sem fonte, reserve a tarde.","**15h00, Convento dos Capuchos:** Cerca de 1h. Das 9h00 às 17h30. € 11 (cerca de R$ 72), última entrada às 17h00. O roteiro oficial mostra Terreiro das Cruzes, Alpendre, Igreja, Claustro e a mata da cerca conventual."]},{"t":"tip","items":["Em 27/02/2026, um aviso oficial dizia que o convento \"permanece encerrado ao público\". O site atual do monumento mostra horário normal. Antes de ir, veja os avisos do Parques de Sintra."],"title":"Capuchos: confirme se está aberto"},{"t":"tip","items":["Obras nas coberturas do palácio, com andaimes, até o 1º trimestre de 2027. Hop On Hop Off de Monserrate fora de serviço. A Casa de Chá reabre em 02/12/2026."],"title":"Avisos de Monserrate"},{"t":"tip","items":["Se o convento estiver fechado, volte a Sintra e use a tarde na Vila Sassetti, de entrada gratuita, das 10h00 às 18h00."],"title":"Plano B"},{"t":"tip","items":["Principal: Parque e Palácio de Monserrate","Grátis: Vila Sassetti, no plano B","Opcional: Convento dos Capuchos, se estiver aberto","**Nas atrações:** Monserrate cerca de 2h30 e Capuchos cerca de 1h","**A pé:** percursos dentro dos parques; o deslocamento entre Sintra, Monserrate e Capuchos é de ônibus","**Esforço:** médio","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** confira os avisos do Parques de Sintra na véspera, porque a abertura dos Capuchos pode mudar."],"title":"Para planejar o Dia 3"},{"t":"p","text":"[Abrir a rota do Dia 3 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Esta%C3%A7%C3%A3o%20de%20Sintra&waypoints=Parque%20e%20Pal%C3%A1cio%20de%20Monserrate&destination=Convento%20dos%20Capuchos&travelmode=transit)"},{"t":"passeio","busca":"Sintra Monserrate passeio","title":"Passeios para Monserrate e Capuchos"},{"t":"h","text":"Cabo da Roca e Queluz","label":"Dia 4"},{"t":"p","text":"\"O ponto mais ocidental da Europa continental\" de manhã e o Palácio de Queluz à tarde."},{"t":"img","src":"/assets/blog/sintra-cabo-da-roca.jpg","alt":"Farol e falésias do Cabo da Roca, com o Atlântico ao fundo","caption":"Farol e falésias do Cabo da Roca, com o Atlântico ao fundo.","credit":"Foto: Miguel Almeida / Pexels","w":1000,"h":667},{"t":"ul","items":["**9h00, Estação de Sintra:** Ônibus 1253 até o Cabo da Roca. Horário: confirme no site da Carris Metropolitana.","**10h00, Farol do Cabo da Roca:** Cerca de 1h30. Pátio e centro interpretativo até as 17h30, última entrada às 17h00. Visita essencial: € 5 (cerca de R$ 33). Panorâmica: € 10 (cerca de R$ 65).","**12h00, Volta a Sintra:** De ônibus 1253, e almoço. Veja a seção Sabores.","**14h00, Trem:** Linha de Sintra até Queluz-Belas ou Monte Abraão. Tempo e tarifa: confirme no site da CP.","**15h00, Palácio de Queluz:** Cerca de 2h. Último bilhete e última entrada às 17h30. O palácio fecha às 18h00 e os jardins às 18h30. € 13 (cerca de R$ 85). O roteiro oficial cita Sala do Trono, Sala da Música, Sala dos Embaixadores, Canal dos Azulejos e os jardins.","**17h30, Fim do roteiro:** Volta a Lisboa no trem da Linha de Sintra."]},{"t":"tip","items":["A bilheteria de Queluz fecha das 12h00 às 13h00 e as instalações sanitárias estão em remodelação. Do trem, desça em Queluz-Belas ou Monte Abraão, a cerca de 1 km do palácio. De Cascais, o ônibus 1624 vai até Portela de Sintra."],"title":"Antes de ir"},{"t":"tip","items":["Principal: Farol do Cabo da Roca e Palácio de Queluz","Grátis: sem atração gratuita neste dia","Opcional: Cabo da Roca panorâmica e Queluz só jardins","**Nas atrações:** cerca de 3h30","**A pé:** cerca de 1 km entre a estação de trem (Queluz-Belas ou Monte Abraão) e o palácio","**Esforço:** dia de deslocamentos de ônibus e trem, com visitas de cerca de 3h30 no total","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** deixe este dia para o fim da viagem e confirme os horários do 1253 e do trem antes de sair."],"title":"Para planejar o Dia 4"},{"t":"p","text":"[Abrir a rota do Dia 4 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Esta%C3%A7%C3%A3o%20de%20Sintra&waypoints=Farol%20do%20Cabo%20da%20Roca&destination=Pal%C3%A1cio%20Nacional%20de%20Queluz&travelmode=transit)"},{"t":"passeio","busca":"Sintra Cabo da Roca Queluz passeio","title":"Passeios para o Cabo da Roca e Queluz"},{"t":"h","text":"Palácio da Pena: como visitar","label":"Atração principal"},{"t":"p","text":"A visita essencial custa € 20 (cerca de R$ 130), mas o que decide o dia é o horário: o ingresso vale só na data e na hora escolhidas."},{"t":"ul","items":["**Dia e hora marcados:** O acesso ao interior só vale na data e na hora do bilhete. A hora é a de entrada no palácio, não no parque.","**Sem tolerância, para os dois lados:** Chegar antes ou depois da hora reservada impede a entrada. Faltar não dá troca nem reembolso.","**Parque e transfer:** Preveja cerca de 30 minutos entre a entrada do parque e o palácio. Um pequeno transfer sai da entrada principal e passa a cada 15 minutos, com bilhete comprado antes: ida e volta, + € 4,50 (cerca de R$ 30).","**Visitas:** Essencial: € 20 (cerca de R$ 130), Ala Nova e parque. Total: € 45 (cerca de R$ 292), com os apartamentos privados. Só o parque: € 12 (cerca de R$ 78).","**Reagendar:** A compra online antecipada permite reagendar dia e hora no site por um ano. Os bilhetes do Parques de Sintra não são reembolsáveis, salvo cancelamento ou alteração de data pela gestora."]},{"t":"tip","items":["Palácio das 9h30 às 18h30; parque das 9h00 às 19h00, com última entrada às 18h00. Há armários para mochila na entrada principal."],"title":"Horário do palácio"},{"t":"h","text":"Trem e ônibus","label":"Na prática"},{"t":"p","text":"De Lisboa a Sintra vai o trem da CP, Linha de Sintra, saindo de Oriente, Rossio ou Entrecampos."},{"t":"ul","items":["**Lisboa a Sintra:** O Rossio liga ao metrô em Restauradores. Tempo, frequência e tarifa: confirme no site da CP.","**Ônibus 434 e 435 (Scotturb):** O 434, circuito da Pena, circula todos os dias das 8h50 às 18h40, em média a cada 10 minutos (Castelo dos Mouros, Pena, Palácio Nacional). O 435, circuito de Monserrate, das 9h00 às 18h30 (Regaleira, Seteais, Monserrate).","**Bilhete de 24 horas (434 e 435):** Vale 24 horas após a primeira validação, só para esses ônibus; não inclui entradas; Lisboacard não é aceito. O operador mostra dois preços: confirme o certo no site da Sintra434.","**Ônibus 1253 (Carris Metropolitana):** Vai de Sintra a Monserrate, Capuchos e Cabo da Roca. Horários e tarifa: confirme no site da operadora.","**Carro particular:** Não é permitido nos acessos à Pena, ao Castelo dos Mouros, ao parque e ao Chalet da Condessa d''Edla; no centro histórico, só moradores.","**Nos parques:** Pena Shuttle, a cada 15 minutos. Hop On Hop Off da Pena: € 4,50 (cerca de R$ 30); o de Monserrate está fora de serviço."]},{"t":"tip","items":["Este guia não traz preço de táxi nem de TVDE porque não achamos fonte oficial."],"title":"Táxi e TVDE"},{"t":"h","text":"Onde comer: travesseiro e cafetarias","label":"Sabores"},{"t":"p","text":"O travesseiro é \"um dos ex-libris de Sintra\"."},{"t":"ul","items":["**Travesseiro de Sintra:** Os mais famosos \"são feitos na Piriquita, Antiga Casa de Queijadas\", na Rua das Padarias 1, fundada em 1862. Preço e horário: confirme no local.","**Cafetarias dos monumentos:** Pratos quentes, saladas, sanduíches, pastelaria e doces regionais (o site não diz quais). Na Pena: Restaurante do Palácio das 10h30 às 17h30; Cafetaria do Palácio das 10h00 às 18h00 (última entrada às 17h45); Quiosque do Picadeiro das 10h00 às 18h00."]},{"t":"tip","items":["Cafetaria dos Lagos (Pena), cafetarias do Castelo dos Mouros e Cafetaria do Pátio dos Leões estão temporariamente fechadas. A Casa de Chá de Monserrate reabre em 02/12/2026. Veja os avisos do Parques de Sintra."],"title":"Fechadas por enquanto"},{"t":"tip","items":["Este guia não traz preço de refeição porque não achamos fonte oficial. Confira o cardápio no local."],"title":"Preços de refeição"},{"t":"tip","items":["**Dica da Rota Certa:** no Dia 2, leve água e um lanche, porque várias cafetarias da serra estão fechadas. As cafetarias atendem necessidades alimentares específicas se avisadas no local."]},{"t":"h","text":"Documentos e antes de ir","label":"Checklist"},{"t":"tip","items":["O Brasil está na lista de isentos de visto para estadas de até 90 dias em qualquer período de 180. O passaporte deve ter sido emitido nos últimos 10 anos e valer 3 meses após a saída prevista da UE."],"title":"Passaporte, sem visto para turismo"},{"t":"ul","items":["**Na chegada, EES:** Desde 10/04/2026, a fronteira Schengen registra passaporte, digitais, imagem facial e datas de entrada e saída. O pré-registro pelo app Travel to Europe é opcional.","**ETIAS: ainda não vale:** A página oficial diz que não está em operação e que a UE avisará a data meses antes. Confira o site oficial do ETIAS antes de comprar a passagem.","**Motivo e dinheiro:** É preciso justificar o motivo da estada e ter meios financeiros suficientes. Confira as regras de entrada vigentes nos sites oficiais."]},{"t":"tip","items":["Passaporte válido 3 meses além da saída.","Ingressos da Pena e da Regaleira, com dia e hora.","Avisos do Parques de Sintra e se os Capuchos abrem."],"title":"Checklist"},{"t":"p","text":"Bilhetes do Parques de Sintra não são reembolsáveis, salvo cancelamento ou alteração de data pela gestora. Regaleira: em geral, sem reembolso nem troca."},{"t":"h","text":"Orçamento","label":"Planejamento"},{"t":"p","text":"O preço da passagem não é o preço da viagem."},{"t":"ul","items":["**Dia 1, Palácio Nacional:** € 13 (cerca de R$ 85)","**Dia 1, Quinta da Regaleira:** € 20 (cerca de R$ 130)","**Dia 2, Castelo dos Mouros:** € 12 (cerca de R$ 78)","**Dia 2, Pena (visita essencial):** € 20 (cerca de R$ 130)","**Dia 3, Monserrate:** € 12 (cerca de R$ 78)","**Dia 3, Convento dos Capuchos:** € 11 (cerca de R$ 72)","**Dia 4, Cabo da Roca (essencial):** € 5 (cerca de R$ 33)","**Dia 4, Palácio e Jardins de Queluz:** € 13 (cerca de R$ 85)","**Total de entradas:** € 106 (cerca de R$ 686)"]},{"t":"p","text":"Valores por adulto de 18 a 64 anos. O Parques de Sintra não informa a data de vigência dos preços: confirme o valor no site antes de ir. Cotação: euro de venda do Banco Central em 19/11/2026, € 1 = R$ 6,4672. O total sai da soma em euros e cada linha é arredondada para cima, por isso a soma das linhas em reais fica um pouco acima do total. Não prometemos que os valores continuem iguais. No cartão entram o IOF e o câmbio do banco."},{"t":"tip","items":["Pena Visita Total: € 45 (cerca de R$ 292).","Transfer da Pena: € 4,50 (cerca de R$ 30).","Cabo da Roca panorâmica: € 10 (cerca de R$ 65).","Queluz só jardins: € 6 (cerca de R$ 39).","Hop On Hop Off da Pena: € 4,50 (cerca de R$ 30)."],"title":"Opcionais, por adulto"},{"t":"tip","items":["Ônibus 434 e 435 (o site do operador mostra dois preços para o bilhete de 24 horas), ônibus 1253, trem da CP, táxi, passagem aérea, hospedagem, refeições e seguro."],"title":"Fora desta conta"},{"t":"pdf","href":"/guias/sintra-em-4-dias.pdf","note":"Leve o roteiro, as rotas e o orçamento no celular. Grátis, sem cadastro."},{"t":"h","text":"Valores oficiais e fontes","label":"Transparência"},{"t":"p","text":"Conferido em 19/11/2026 nos sites abaixo. Reais pela cotação de venda do Banco Central de 19/11/2026: € 1 = R$ 6,4672. Regras, horários e preços mudam: confirme nos sites oficiais antes de ir."},{"t":"tip","items":["Parques de Sintra: [horários e preços](https://www.parquesdesintra.pt/pt/planear-a-visita/horarios-e-precos/), [opening times](https://www.parquesdesintra.pt/en/plan-your-visit/opening-times-and-prices/), [como chegar](https://www.parquesdesintra.pt/pt/planear-a-visita/como-chegar/) e [avisos](https://www.parquesdesintra.pt/pt/avisos/)","Pena: [bilhetes](https://www.parquesdesintra.pt/pt/planear-a-visita/bilhetes-palacio-da-pena/), [parque e palácio](https://www.parquesdesintra.pt/en/parks-monuments/park-and-national-palace-of-pena/), [visita essencial](https://www.parquesdesintra.pt/en/parks-monuments/park-and-national-palace-of-pena/essential-visit/) e [visita completa](https://www.parquesdesintra.pt/en/parks-monuments/park-and-national-palace-of-pena/complete-visit/)","Monumentos: [Castelo dos Mouros](https://www.parquesdesintra.pt/en/parks-monuments/the-moorish-castle/), [Palácio Nacional](https://www.parquesdesintra.pt/en/parks-monuments/national-palace-of-sintra/), [Monserrate](https://www.parquesdesintra.pt/pt/parques-monumentos/parque-e-palacio-de-monserrate/), [Capuchos](https://www.parquesdesintra.pt/pt/parques-monumentos/convento-dos-capuchos/), [Cabo da Roca](https://www.parquesdesintra.pt/pt/parques-monumentos/farol-do-cabo-da-roca/) e [Queluz](https://www.parquesdesintra.pt/pt/parques-monumentos/palacio-nacional-e-jardins-de-queluz/)","Avisos e roteiros: [temporais de 2026](https://www.parquesdesintra.pt/pt/avisos/260128-depressao-kristin/), [Nascente a Poente](https://www.parquesdesintra.pt/pt/planear-a-visita/roteiros/sintra-de-nascente-a-poente/), [Costa e Serra](https://www.parquesdesintra.pt/pt/planear-a-visita/roteiros/descobrir-a-costa-e-a-serra/) e [cafetarias](https://www.parquesdesintra.pt/en/plan-your-visit/cafeterias-and-restaurants/)","Regaleira: [visitas](https://www.regaleira.pt/en/visitas), [preços](https://www.regaleira.pt/en/destaques/2025-entrance-fees-2026/) e [bilheteria oficial](https://regaleira.byblueticket.pt/)","Transporte: [Sintra434 (Scotturb)](https://www.sintra434.com/pt) e [CP, Linha de Sintra](https://cp.pt/info/en/w/institucional/the-sintra-line)","Travesseiros: [Visit Sintra](https://visitsintra.travel/en/eat-drink/regional-flavours/travesseiros)","Entrada: [Regulamento 2018/1806](https://eur-lex.europa.eu/legal-content/PT/TXT/?uri=CELEX:32018R1806), [Your Europe](https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm), [diferenças entre EES e ETIAS](https://home-affairs.ec.europa.eu/news/main-differences-between-ees-and-etias-what-travellers-need-know-2026-04-28_en), [EES](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/entry-exit-system_en) e [ETIAS](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/european-travel-information-authorisation-system_en)","Câmbio: [Banco Central, 19/11/2026](https://www4.bcb.gov.br/Download/fechamento/20261119.csv)"],"title":"Fontes oficiais, conferidas em 19/11/2026"},{"t":"tip","items":["Data de vigência dos preços do Parques de Sintra: os valores de entrada podem ter mudado","Última entrada do Palácio da Pena: a tabela oficial mostra 17h30 e 18h00, confirme na compra","Horários de início da visita total da Pena (confirme os horários disponíveis na compra)","Horários do Palácio Nacional e do Castelo dos Mouros: o Turismo de Lisboa diverge do Parques de Sintra, e o guia usa o Parques de Sintra","Se o prazo de um ano para reagendar o ingresso conta da compra ou da visita","Se o portão do Chalet da Condessa d''Edla fecha ao meio-dia (confirme no site oficial)","Se o Convento dos Capuchos está aberto (aviso de fevereiro de 2026 diz encerrado, o site atual mostra horário normal)","Avisos de 2026 sobre temporais e obras: podem estar superados, veja os avisos do Parques de Sintra no dia","Preço do bilhete de 24 horas dos ônibus 434 e 435 (o operador mostra dois valores) e última saída da Pena","Horários, frequência e tarifa do ônibus 1253 (Carris Metropolitana)","Tempo, frequência e tarifa do trem da CP de Lisboa a Sintra e de Sintra a Queluz","Tempo de ônibus entre as paradas e duração de cada visita: só estimativas da Rota Certa","Tempo a pé da estação de Sintra ao Palácio Nacional (o site oficial cita 10 a 15 minutos, sem dizer se a pé)","Dias de fechamento dos monumentos do Parques de Sintra (só a Regaleira informa os dela)","Preço e horário do travesseiro na Piriquita","Valor dos meios de subsistência na entrada em Portugal e data de início do ETIAS","Táxi, TVDE, preços de refeição, hospedagem e taxa turística: fora do guia"],"title":"O que este guia não informa"},{"t":"p","text":"Preços, horários e regras mudam: confira nas fontes acima antes de ir. As estimativas de tempo e esforço, os horários sugeridos e as dicas marcadas como da Rota Certa são recomendações nossas, não dados oficiais."},{"t":"p","text":"Foto de capa: Niklas Jeromin / Pexels."},{"t":"whatsapp"},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 16);
